def U(type_, number, name, slug, rationale, comps, case, strat, guidelines, materials, *_ignored):
    return dict(type=type_, number=number, name=name, racgp_url=BASE+slug, rationale=rationale,
                competencies=comps, case_example=case, learning_strategies=strat,
                guidelines=guidelines, materials=materials)

