# validate uniqueness and count
names = [u["name"] for u in units]
assert len(names) == len(set(names)), "duplicate unit names"
core = [u for u in units if u["type"]=="core"]; ctx = [u for u in units if u["type"]=="contextual"]
print(f"units: {len(units)} (core {len(core)}, contextual {len(ctx)})")

out = dict(units=units)
(D / "curriculum_v3.json").write_text(json.dumps(out, indent=1), encoding="utf-8")
